 		phy_sanitize_settings(phydev);

 	err = phy_config_aneg(phydev);
 	if (err < 0)
-		goto out_unlock;
+		return err;

 	if (phy_is_started(phydev))
 		err = phy_check_link_status(phydev);
-out_unlock:
+
+	return err;
+}
