+{
+	int err;
+
+	mutex_lock(&phydev->lock);
+	err = _phy_start_aneg(phydev);
 	mutex_unlock(&phydev->lock);

 	return err;
 }
 EXPORT_SYMBOL(phy_start_aneg);


